cat > /tmp/partscheck.ts <<'EOF'
import { ZimmFooter } from './overrides/app/theme/components/footer';
import { ZimmTextInput } from './overrides/app/theme/components/zimmTextInput';

const report = (name: string, parts: readonly string[], keys: string[]) => {
  const p = new Set(parts); const k = new Set(keys);
  console.log(`\n### ${name}`);
  console.log(`  parts: ${parts.length}  baseStyle keys: ${keys.length}`);
  console.log(`  in parts, NOT in baseStyle: ${[...p].filter(x => !k.has(x)).join(', ') || '(none)'}`);
  console.log(`  in baseStyle, NOT in parts: ${[...k].filter(x => !p.has(x)).join(', ') || '(none)'}`);
  const dupes = parts.filter((x, i) => parts.indexOf(x) !== i);
  console.log(`  duplicate parts entries: ${dupes.join(', ') || '(none)'}`);
};

report('ZimmFooter', ZimmFooter.parts, Object.keys(ZimmFooter.baseStyle));
const tiKeys = Object.keys(ZimmTextInput.baseStyle({}));
report('ZimmTextInput', ZimmTextInput.parts, tiKeys);
// also probe every state combo for key drift
const combos = [{}, {inverse:true}, {disabled:true}, {hasError:true}, {focused:true}, {filled:true}, {inverse:true,disabled:true,hasError:true,focused:true,filled:true}];
const sets = combos.map(c => Object.keys(ZimmTextInput.baseStyle(c as any)).sort().join('|'));
console.log('  key set stable across all state combos:', new Set(sets).size === 1);
EOF
npx tsx /tmp/partscheck.ts 2>&1 | tail -30

