cat > $R/.varcheck.tmp.ts <<'EOF'
import { zimmTokens } from './overrides/app/theme/foundation/zimmTokens';
import { execSync } from 'child_process';
const defined = new Set(Object.keys(zimmTokens as Record<string, string>));
console.log('vars defined in zimmTokens.ts:', defined.size);
// gather every --zimm-* reference in the audit surface
const files = execSync(
  `grep -rlo -- '--zimm-' overrides/app/components overrides/app/theme overrides/app/hooks 2>/dev/null || true`,
  { encoding: 'utf8' }
).trim().split('\n').filter(Boolean);
const missing = new Map<string, string[]>();
let total = 0;
for (const f of files) {
  const src = require('fs').readFileSync(f, 'utf8').split('\n');
  src.forEach((line: string, i: number) => {
    for (const m of line.matchAll(/--zimm-[a-zA-Z0-9-]+/g)) {
      total++;
      if (!defined.has(m[0])) {
        if (!missing.has(m[0])) missing.set(m[0], []);
        missing.get(m[0])!.push(`${f}:${i + 1}`);
      }
    }
  });
}
console.log('total --zimm-* references scanned:', total);
if (missing.size === 0) console.log('\nALL REFERENCES RESOLVE — no undefined --zimm-* var.');
else {
  console.log('\nUNDEFINED VARS:');
  for (const [v, locs] of missing) console.log(`  ${v}\n      ${locs.join('\n      ')}`);
}
EOF
cd $R && npx tsx ./.varcheck.tmp.ts 2>&1 | tail -40; rm -f $R/.varcheck.tmp.ts

