   110	          />
   111	        </chakra.div>
   112	        {/* Clear-✕ — opt-in only, see `clearable` above. Renders before {trailing}, so a
   113	            field that opts into both shows clear then trailing icon. */}
   114	        {clearable && !disabled && value.length > 0 && (
   115	          <chakra.button type="button" aria-label="Clear input" onClick={handleClear} __css={styles.clearButton}>
   116	            <ZimmIcon type="close" size="sm" aria-hidden={true} />
   117	          </chakra.button>
   118	        )}
   119	        {trailing}
   120	      </chakra.div>
   121	      {helperText && (
   122	        <chakra.p id={helperId} __css={styles.helper}>
   123	          {helperText}
   124	        </chakra.p>
   125	      )}
   126	      {errorText && (
   127	        <chakra.p id={errorId} role="alert" __css={styles.error}>
   128	          {errorText}
   129	        </chakra.p>
   130	      )}
   131	    </chakra.div>
   132	  );
   133	};

