  1	/**
  2	 * Recipe guards — regression tests for three failure modes that reached a feature branch
  3	 * despite passing `tsc`, `eslint`, `vitest`, CodeRabbit and the Storybook a11y run.
  4	 *
  5	 * All three share a shape: the value is a *valid* `SystemStyleObject` entry, so TypeScript is
  6	 * satisfied; no lint rule covers it; and nothing asserts layout. Each one renders plausible,
  7	 * wrong output that is only visible by opening the page.
  8	 *
  9	 *   1. A spacing-scale key on a sizing property. Chakra resolves `width`/`height`/`boxSize`
 10	 *      through `theme.sizes`, not `theme.space`. The Zimmermann named scale is registered as
 11	 *      `space` only (deliberately — see foundation/sizes.ts), so `width: 'xl'` silently reads
 12	 *      Chakra's default `sizes.xl` = 36rem. It shipped a 576px icon and collapsed the footer.
 13	 *
 14	 *   2. A recipe key that collides with a base SFCC recipe. `theme/index.ts` composes with
 15	 *      `extendTheme(baseTheme, overrides)`, which DEEP MERGES — a recipe named `Footer` does
 16	 *      not replace SFCC's `Footer`, it inherits it. Shared part names then pick up base
 17	 *      properties, and a key you add that the base lacks is appended last, so a CSS shorthand
 18	 *      can silently reset a longhand the base declared earlier.
 19	 *
 20	 *   3. A bare scale key inside a compound shorthand. Chakra resolves a token only when it is
 21	 *      the entire value; `padding: 'xs 0'` is emitted verbatim, the browser rejects the
 22	 *      declaration, and the padding does not apply at all.
 23	 */
 24	import { describe, expect, test } from 'vitest';
 25	import theme from '../index';
 26	import { components } from './index';
 27	import { spacing } from '../foundation/spacing';
 28	
 29	const SPACING_KEYS = Object.keys(spacing);
 30	
 31	const SIZING_PROPS = new Set([
 32	  'width',
 33	  'height',
 34	  'minWidth',
 35	  'maxWidth',
 36	  'minHeight',
 37	  'maxHeight',
 38	  'boxSize',
 39	  'w',
 40	  'h',
